package info.maxbehr.arch.jilt;

import java.time.Instant;
import java.util.UUID;
import org.jilt.Builder;
import org.jilt.BuilderStyle;
import org.jspecify.annotations.Nullable;

/**
 * A user account.
 *
 * <p>The STAGED builder generated by Jilt forces every non-null component to be set before {@code
 * build()} becomes available – a forgotten field is a compile error, not a silent {@code null} or
 * {@code false}. Components annotated with {@code @Nullable} are optional and may be skipped.
 */
@Builder(style = BuilderStyle.STAGED)
public record UserAccount(
    UUID id,
    String username,
    String email,
    String firstName,
    String lastName,
    boolean active,
    boolean emailVerified,
    Instant createdAt,
    @Nullable String phoneNumber,
    @Nullable Instant lastLoginAt) {}
